import { useState, useEffect } from "react";

// API giả lập: trả Promise sau 30 ms; id = 0 thì lỗi
const fetchUser = (id) =>
  new Promise((resolve, reject) =>
    setTimeout(() => (id === 0 ? reject(new Error("Không tìm thấy")) : resolve({ id, name: "User " + id })), 30)
  );

export default function App() {
  const [id, setId] = useState(1);
  const [state, setState] = useState({ status: "loading" });

  useEffect(() => {
    let ignore = false;                       // chặn kết quả của yêu cầu CŨ (race condition)
    setState({ status: "loading" });
    fetchUser(id)
      .then((user) => !ignore && setState({ status: "success", user }))
      .catch((e) => !ignore && setState({ status: "error", message: e.message }));
    return () => { ignore = true; };
  }, [id]);

  return (
    <div>
      <button id="next" onClick={() => setId(id + 1)}>Tiếp</button>
      {state.status === "loading" && <p id="loading">Đang tải…</p>}
      {state.status === "error" && <p id="err">{state.message}</p>}
      {state.status === "success" && <p id="name">{state.user.name}</p>}
    </div>
  );
}

